import React, { useState, useEffect } from "react";
import { useNavigate } from "react-router-dom";

const Profile = (props) => {
  const [userInfo, setUserInfo] = useState({
    name: "",
    email: "",
    bio: "",
    profileImage: "",
    preferences: {
      theme: "light",
      emailNotifications: true,
      autoSave: true,
      defaultSort: "dateCreated"
    }
  });
  const [passwords, setPasswords] = useState({
    currentPassword: "",
    newPassword: "",
    confirmPassword: ""
  });
  const [activeTab, setActiveTab] = useState("profile");
  const [loading, setLoading] = useState(false);
  const navigate = useNavigate();
  const host = "http://localhost:5000";

  useEffect(() => {
    if (!localStorage.getItem('token')) {
      navigate("/login");
      return;
    }
    fetchUserProfile();
  }, [navigate]);

  const fetchUserProfile = async () => {
    try {
      const token = localStorage.getItem('token');
      const response = await fetch(`${host}/api/auth/getuser`, {
        method: "GET",
        headers: {
          "Content-Type": "application/json",
          "auth-token": token,
        }
      });
      
      const userData = await response.json();
      if (response.ok) {
        setUserInfo({
          name: userData.name || "",
          email: userData.email || "",
          bio: userData.bio || "",
          profileImage: userData.profileImage || "",
          preferences: {
            theme: userData.preferences?.theme || "light",
            emailNotifications: userData.preferences?.emailNotifications !== false,
            autoSave: userData.preferences?.autoSave !== false,
            defaultSort: userData.preferences?.defaultSort || "dateCreated"
          }
        });
      }
    } catch (error) {
      console.error('Error fetching user profile:', error);
      props.showAlert("Error loading profile", "danger");
    }
  };

  const handleProfileUpdate = async (e) => {
    e.preventDefault();
    setLoading(true);

    try {
      const token = localStorage.getItem('token');
      const response = await fetch(`${host}/api/auth/updateprofile`, {
        method: "PUT",
        headers: {
          "Content-Type": "application/json",
          "auth-token": token,
        },
        body: JSON.stringify({
          name: userInfo.name,
          bio: userInfo.bio,
          profileImage: userInfo.profileImage,
          preferences: userInfo.preferences
        }),
      });

      const result = await response.json();
      if (response.ok) {
        props.showAlert("Profile updated successfully", "success");
      } else {
        props.showAlert(result.message || "Failed to update profile", "danger");
      }
    } catch (error) {
      console.error('Error updating profile:', error);
      props.showAlert("Error updating profile", "danger");
    } finally {
      setLoading(false);
    }
  };

  const handlePasswordChange = async (e) => {
    e.preventDefault();
    
    if (passwords.newPassword !== passwords.confirmPassword) {
      props.showAlert("New passwords don't match", "danger");
      return;
    }

    if (passwords.newPassword.length < 5) {
      props.showAlert("Password must be at least 5 characters long", "danger");
      return;
    }

    setLoading(true);

    try {
      const token = localStorage.getItem('token');
      const response = await fetch(`${host}/api/auth/changepassword`, {
        method: "PUT",
        headers: {
          "Content-Type": "application/json",
          "auth-token": token,
        },
        body: JSON.stringify({
          currentPassword: passwords.currentPassword,
          newPassword: passwords.newPassword
        }),
      });

      const result = await response.json();
      if (response.ok) {
        setPasswords({ currentPassword: "", newPassword: "", confirmPassword: "" });
        props.showAlert("Password changed successfully", "success");
      } else {
        props.showAlert(result.message || "Failed to change password", "danger");
      }
    } catch (error) {
      console.error('Error changing password:', error);
      props.showAlert("Error changing password", "danger");
    } finally {
      setLoading(false);
    }
  };

  const handleImageUpload = (e) => {
    const file = e.target.files[0];
    if (file) {
      const reader = new FileReader();
      reader.onload = (event) => {
        setUserInfo({ ...userInfo, profileImage: event.target.result });
      };
      reader.readAsDataURL(file);
    }
  };

  const onProfileChange = (e) => {
    const { name, value, type, checked } = e.target;
    
    if (name.startsWith('preferences.')) {
      const prefKey = name.split('.')[1];
      setUserInfo({
        ...userInfo,
        preferences: {
          ...userInfo.preferences,
          [prefKey]: type === 'checkbox' ? checked : value
        }
      });
    } else {
      setUserInfo({ ...userInfo, [name]: value });
    }
  };

  const onPasswordChange = (e) => {
    setPasswords({ ...passwords, [e.target.name]: e.target.value });
  };

  const deleteAccount = async () => {
    const confirmDelete = window.confirm(
      "Are you sure you want to delete your account? This action cannot be undone and will delete all your notes."
    );
    
    if (!confirmDelete) return;

    const finalConfirm = window.prompt(
      "Type 'DELETE' to confirm account deletion:"
    );

    if (finalConfirm !== 'DELETE') {
      props.showAlert("Account deletion cancelled", "info");
      return;
    }

    try {
      const token = localStorage.getItem('token');
      const response = await fetch(`${host}/api/auth/deleteaccount`, {
        method: "DELETE",
        headers: {
          "Content-Type": "application/json",
          "auth-token": token,
        }
      });

      if (response.ok) {
        localStorage.removeItem('token');
        props.showAlert("Account deleted successfully", "success");
        navigate("/signup");
      } else {
        const result = await response.json();
        props.showAlert(result.message || "Failed to delete account", "danger");
      }
    } catch (error) {
      console.error('Error deleting account:', error);
      props.showAlert("Error deleting account", "danger");
    }
  };

  return (
    <div className="container mt-4">
      <div className="row">
        <div className="col-12">
          <div className="card">
            <div className="card-header">
              <h2 className="mb-0">
                <i className="fas fa-user-cog me-2"></i>Profile Management
              </h2>
            </div>
            <div className="card-body">
              {/* Navigation Tabs */}
              <ul className="nav nav-tabs mb-4" role="tablist">
                <li className="nav-item" role="presentation">
                  <button
                    className={`nav-link ${activeTab === 'profile' ? 'active' : ''}`}
                    onClick={() => setActiveTab('profile')}
                    type="button"
                  >
                    <i className="fas fa-user me-2"></i>Profile Info
                  </button>
                </li>
                <li className="nav-item" role="presentation">
                  <button
                    className={`nav-link ${activeTab === 'password' ? 'active' : ''}`}
                    onClick={() => setActiveTab('password')}
                    type="button"
                  >
                    <i className="fas fa-lock me-2"></i>Change Password
                  </button>
                </li>
                <li className="nav-item" role="presentation">
                  <button
                    className={`nav-link ${activeTab === 'preferences' ? 'active' : ''}`}
                    onClick={() => setActiveTab('preferences')}
                    type="button"
                  >
                    <i className="fas fa-cog me-2"></i>Preferences
                  </button>
                </li>
                <li className="nav-item" role="presentation">
                  <button
                    className={`nav-link ${activeTab === 'danger' ? 'active' : ''}`}
                    onClick={() => setActiveTab('danger')}
                    type="button"
                  >
                    <i className="fas fa-exclamation-triangle me-2"></i>Danger Zone
                  </button>
                </li>
              </ul>

              {/* Profile Information Tab */}
              {activeTab === 'profile' && (
                <form onSubmit={handleProfileUpdate}>
                  <div className="row">
                    <div className="col-md-4 text-center mb-4">
                      <div className="profile-image-container">
                        {userInfo.profileImage ? (
                          <img
                            src={userInfo.profileImage}
                            alt="Profile"
                            className="rounded-circle profile-image"
                            style={{ width: '150px', height: '150px', objectFit: 'cover' }}
                          />
                        ) : (
                          <div
                            className="rounded-circle bg-secondary d-flex align-items-center justify-content-center profile-image"
                            style={{ width: '150px', height: '150px' }}
                          >
                            <i className="fas fa-user fa-4x text-white"></i>
                          </div>
                        )}
                      </div>
                      <div className="mt-3">
                        <input
                          type="file"
                          id="profileImageUpload"
                          accept="image/*"
                          onChange={handleImageUpload}
                          className="d-none"
                        />
                        <label htmlFor="profileImageUpload" className="btn btn-outline-primary btn-sm">
                          <i className="fas fa-camera me-1"></i>Change Photo
                        </label>
                      </div>
                    </div>

                    <div className="col-md-8">
                      <div className="mb-3">
                        <label htmlFor="name" className="form-label">Full Name</label>
                        <input
                          type="text"
                          className="form-control"
                          id="name"
                          name="name"
                          value={userInfo.name}
                          onChange={onProfileChange}
                          required
                        />
                      </div>

                      <div className="mb-3">
                        <label htmlFor="email" className="form-label">Email Address</label>
                        <input
                          type="email"
                          className="form-control"
                          id="email"
                          name="email"
                          value={userInfo.email}
                          readOnly
                          disabled
                        />
                        <div className="form-text">Email cannot be changed</div>
                      </div>

                      <div className="mb-3">
                        <label htmlFor="bio" className="form-label">Bio</label>
                        <textarea
                          className="form-control"
                          id="bio"
                          name="bio"
                          rows="3"
                          value={userInfo.bio}
                          onChange={onProfileChange}
                          placeholder="Tell us about yourself..."
                        />
                      </div>

                      <button 
                        type="submit" 
                        className="btn btn-primary"
                        disabled={loading}
                      >
                        {loading ? (
                          <>
                            <span className="spinner-border spinner-border-sm me-2" role="status"></span>
                            Updating...
                          </>
                        ) : (
                          <>
                            <i className="fas fa-save me-2"></i>Update Profile
                          </>
                        )}
                      </button>
                    </div>
                  </div>
                </form>
              )}

              {/* Change Password Tab */}
              {activeTab === 'password' && (
                <form onSubmit={handlePasswordChange}>
                  <div className="row justify-content-center">
                    <div className="col-md-6">
                      <div className="mb-3">
                        <label htmlFor="currentPassword" className="form-label">Current Password</label>
                        <input
                          type="password"
                          className="form-control"
                          id="currentPassword"
                          name="currentPassword"
                          value={passwords.currentPassword}
                          onChange={onPasswordChange}
                          required
                        />
                      </div>

                      <div className="mb-3">
                        <label htmlFor="newPassword" className="form-label">New Password</label>
                        <input
                          type="password"
                          className="form-control"
                          id="newPassword"
                          name="newPassword"
                          value={passwords.newPassword}
                          onChange={onPasswordChange}
                          minLength={5}
                          required
                        />
                        <div className="form-text">Password must be at least 5 characters long</div>
                      </div>

                      <div className="mb-3">
                        <label htmlFor="confirmPassword" className="form-label">Confirm New Password</label>
                        <input
                          type="password"
                          className="form-control"
                          id="confirmPassword"
                          name="confirmPassword"
                          value={passwords.confirmPassword}
                          onChange={onPasswordChange}
                          minLength={5}
                          required
                        />
                      </div>

                      <button 
                        type="submit" 
                        className="btn btn-primary"
                        disabled={loading}
                      >
                        {loading ? (
                          <>
                            <span className="spinner-border spinner-border-sm me-2" role="status"></span>
                            Changing...
                          </>
                        ) : (
                          <>
                            <i className="fas fa-key me-2"></i>Change Password
                          </>
                        )}
                      </button>
                    </div>
                  </div>
                </form>
              )}

              {/* Preferences Tab */}
              {activeTab === 'preferences' && (
                <form onSubmit={handleProfileUpdate}>
                  <div className="row">
                    <div className="col-md-6">
                      <h5>Appearance</h5>
                      <div className="mb-3">
                        <label htmlFor="theme" className="form-label">Theme</label>
                        <select
                          className="form-select"
                          id="theme"
                          name="preferences.theme"
                          value={userInfo.preferences.theme}
                          onChange={onProfileChange}
                        >
                          <option value="light">Light</option>
                          <option value="dark">Dark</option>
                          <option value="auto">Auto (System)</option>
                        </select>
                      </div>

                      <div className="mb-3">
                        <label htmlFor="defaultSort" className="form-label">Default Sort Order</label>
                        <select
                          className="form-select"
                          id="defaultSort"
                          name="preferences.defaultSort"
                          value={userInfo.preferences.defaultSort}
                          onChange={onProfileChange}
                        >
                          <option value="dateCreated">Date Created (Newest First)</option>
                          <option value="dateModified">Date Modified (Newest First)</option>
                          <option value="alphabetical">Title (A-Z)</option>
                          <option value="alphabeticalDesc">Title (Z-A)</option>
                        </select>
                      </div>
                    </div>

                    <div className="col-md-6">
                      <h5>Notifications & Features</h5>
                      <div className="mb-3">
                        <div className="form-check">
                          <input
                            className="form-check-input"
                            type="checkbox"
                            id="emailNotifications"
                            name="preferences.emailNotifications"
                            checked={userInfo.preferences.emailNotifications}
                            onChange={onProfileChange}
                          />
                          <label className="form-check-label" htmlFor="emailNotifications">
                            Email Notifications
                          </label>
                        </div>
                      </div>

                      <div className="mb-3">
                        <div className="form-check">
                          <input
                            className="form-check-input"
                            type="checkbox"
                            id="autoSave"
                            name="preferences.autoSave"
                            checked={userInfo.preferences.autoSave}
                            onChange={onProfileChange}
                          />
                          <label className="form-check-label" htmlFor="autoSave">
                            Auto-save notes while typing
                          </label>
                        </div>
                      </div>
                    </div>
                  </div>

                  <button 
                    type="submit" 
                    className="btn btn-primary"
                    disabled={loading}
                  >
                    {loading ? (
                      <>
                        <span className="spinner-border spinner-border-sm me-2" role="status"></span>
                        Saving...
                      </>
                    ) : (
                      <>
                        <i className="fas fa-save me-2"></i>Save Preferences
                      </>
                    )}
                  </button>
                </form>
              )}

              {/* Danger Zone Tab */}
              {activeTab === 'danger' && (
                <div className="row justify-content-center">
                  <div className="col-md-8">
                    <div className="alert alert-danger">
                      <h5><i className="fas fa-exclamation-triangle me-2"></i>Danger Zone</h5>
                      <p>The following actions are irreversible. Please proceed with caution.</p>
                    </div>

                    <div className="card border-danger">
                      <div className="card-header bg-danger text-white">
                        <h6 className="mb-0">Delete Account</h6>
                      </div>
                      <div className="card-body">
                        <p>
                          Once you delete your account, there is no going back. This will permanently delete:
                        </p>
                        <ul>
                          <li>All your notes and attachments</li>
                          <li>Your profile information</li>
                          <li>All associated data</li>
                        </ul>
                        <button 
                          type="button" 
                          className="btn btn-danger"
                          onClick={deleteAccount}
                        >
                          <i className="fas fa-trash me-2"></i>Delete My Account
                        </button>
                      </div>
                    </div>
                  </div>
                </div>
              )}
            </div>
          </div>
        </div>
      </div>

      <style jsx>{`
        .profile-image {
          border: 3px solid #dee2e6;
          transition: border-color 0.3s;
        }
        .profile-image:hover {
          border-color: #007bff;
        }
        .nav-tabs .nav-link {
          border: none;
          color: #6c757d;
        }
        .nav-tabs .nav-link.active {
          background-color: #007bff;
          color: white;
          border-radius: 0.375rem 0.375rem 0 0;
        }
        .nav-tabs .nav-link:hover {
          border: none;
          background-color: #e9ecef;
        }
        .nav-tabs .nav-link.active:hover {
          background-color: #0056b3;
        }
      `}</style>
    </div>
  );
};

export default Profile;
